import java.math.*;
class Solution {
    public static boolean checkString(String str) {
        boolean flagL = false;
        boolean flagN = false;
        for (char c : str.toCharArray()) {
            if (Character.isLetter(c)) {
                flagL = true;
            }
            if (Character.isDigit(c)) {
                flagN = true;
            }
        }
        return flagL && flagN;
    }
}

