class Solution {
    public static int power(int a, int b) {
        if (b == 0) {
            return 1;
        } else if (a == 0) {
            return 0;
        } else if (b == 1) {
            return a;
        }

        HashMap<Integer, Integer> memo = new HashMap<>();
        memo.put(0, 1);
        memo.put(1, a);

        for (int i = 2; i <= b; i++) {
            memo.put(i, memo.getOrDefault(i - 1, 1) * memo.getOrDefault(i - 2, 1));
        }

        return memo.get(b);
    }
}

