function counting_sort(my_list) {
    let max_value = 0;
    for (let i = 0; i < my_list.length; i++) {
        if (my_list[i] > max_value) {
            max_value = my_list[i];
        }
    }
    let buckets = new Array(max_value + 1).fill(0);
    for (let i = 0; i < my_list.length; i++) {
        buckets[my_list[i]] += 1;
    }
    let index = 0;
    for (let j = 0; j <= max_value; j++) {
        for (let a = 0; a < buckets[j]; a++) {
            my_list[index] = j;
            index += 1;
        }
    }
    return my_list;
}

