function decimal_To_Binary(N) {
    let B_Number = 0;
    let cnt = 0;
    while (N!= 0) {
        let rem = N % 2;
        let c = Math.pow(10, cnt);
        B_Number += rem * c;
        N = Math.floor(N / 2);
        cnt++;
    }
    return B_Number.toString(2);
}

